	const _getFullPath = relativePath => path.resolve(pathPrefix, relativePath);
	const _getPaths = function (input) {
		// Accepts either a single string path or an array of string paths, and always returns a (possibly empty) array
		if (typeof input === 'string') {
			return [input];
