			let thumbs = await topics.thumbs.get(tid);
			const replacePath = path.posix.join(nconf.get('relative_path'), nconf.get('upload_url'));
			thumbs = thumbs.map(thumb => thumb.url.replace(replacePath, '')).filter(thumbPath => !validator.isURL(thumbPath, {
				require_protocol: true,
			}));
			uploads.push(...thumbs.map(thumbPath => thumbPath.replace(/^-?\/?files\//, 'files/')));
		}

		// Create add/remove sets
		const add = uploads.filter(p => !currentUploads.includes(p));
		const remove = currentUploads.filter(p => !uploads.includes(p));
		await Promise.all([
			Posts.uploads.associate(pid, add),
			Posts.uploads.dissociate(pid, remove),
